import React, { useState } from "react";

const QuizPage = () => {
  const [formData, setFormData] = useState({
    exam: "",
    difficultyLevels: [],
    classYear: "",
    name: "",
    quizMode: "",
    addHints: false,
    answerExplanation: false,
    breakIntoSubtopics: false,
    subjects: [],
    topics: [],
    currentSubject: "",
    currentTopic: "",
    numberOfQuestions: null,
  });

  const [timerOption, setTimerOption] = useState("noTimer");
  const [perQuestionTime, setPerQuestionTime] = useState("");
  const [totalTime, setTotalTime] = useState("");

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const handleDifficultyChange = (e) => {
    const { value, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      difficultyLevels: checked
        ? [...prevData.difficultyLevels, value]
        : prevData.difficultyLevels.filter((level) => level !== value),
    }));
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    console.log(formData);
  };

  const handleAddSubject = () => {
    if (formData.currentSubject.trim()) {
      setFormData((prev) => ({
        ...prev,
        subjects: [...prev.subjects, formData.currentSubject.trim()],
        currentSubject: "",
      }));
    }
  };

  const handleAddTopic = () => {
    if (formData.currentTopic.trim()) {
      setFormData((prev) => ({
        ...prev,
        topics: [...prev.topics, formData.currentTopic.trim()],
        currentTopic: "",
      }));
    }
  };

  const handleTimerChange = (e) => {
    setTimerOption(e.target.value);
    setPerQuestionTime("");
    setTotalTime("");
  };

  return (
    <div className="min-h-screen bg-gray-50 py-10 px-4 sm:px-10">
      <div className="max-w-4xl mx-auto bg-white shadow-md rounded-lg p-8">
        <h1 className="text-3xl font-bold text-center text-blue-600 mb-6">
          Quiz Creation Form
        </h1>
        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="space-y-4">
            <label className="block">
              <span className="text-gray-700 font-medium">Your Name</span>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="What should we call you?"
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                required
              />
            </label>

            <label className="block">
              <span className="text-gray-700 font-medium">Exam Type</span>
              <input
                type="text"
                name="exam"
                value={formData.exam}
                onChange={handleChange}
                placeholder="E.g., Midterm, JEE, etc."
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                required
              />
            </label>

            <label className="block">
              <span className="text-gray-700 font-medium">Class/Year</span>
              <input
                type="text"
                name="classYear"
                value={formData.classYear}
                onChange={handleChange}
                placeholder="E.g., Class 10, First Year"
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                required
              />
            </label>

            <label className="block">
              <span className="text-gray-700 font-medium">
                Number of Questions
              </span>
              <input
                type="number"
                name="numberOfQuestions"
                value={formData.numberOfQuestions}
                onChange={handleChange}
                placeholder="Enter number of questions"
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                required
              />
            </label>
          </div>

          <div>
            <h2 className="text-lg font-bold text-gray-800">Difficulty Levels</h2>
            <div className="mt-3 space-y-2">
              {["Easy", "Medium", "Hard"].map((level) => (
                <label key={level} className="inline-flex items-center">
                  <input
                    type="checkbox"
                    value={level}
                    checked={formData.difficultyLevels.includes(level)}
                    onChange={handleDifficultyChange}
                    className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="ml-2">{level}</span>
                </label>
              ))}
            </div>
          </div>

          <div>
            <h2 className="text-lg font-bold text-gray-800">Additional Features</h2>
            <div className="mt-3 space-y-3">
              {[
                { name: "addHints", label: "Add Hints to Questions" },
                { name: "answerExplanation", label: "Include Answer Explanations" },
                { name: "breakIntoSubtopics", label: "Break Questions into Subtopics" },
              ].map((feature) => (
                <label key={feature.name} className="inline-flex items-center">
                  <input
                    type="checkbox"
                    name={feature.name}
                    checked={formData[feature.name]}
                    onChange={handleChange}
                    className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="ml-2">{feature.label}</span>
                </label>
              ))}
            </div>
          </div>

          <div>
            <h2 className="text-lg font-bold text-gray-800">Subjects & Topics</h2>
            <div className="mt-3 space-y-4">
              <div>
                <label className="block font-medium text-gray-700">
                  Add Subjects:
                </label>
                <input
                  type="text"
                  name="currentSubject"
                  value={formData.currentSubject}
                  onChange={(e) =>
                    setFormData({ ...formData, currentSubject: e.target.value })
                  }
                  placeholder="Subject name"
                  className="mt-1 w-full rounded-md border-gray-300 shadow-sm focus:border-green-500 focus:ring-green-500 sm:text-sm"
                />
                <button
                  type="button"
                  onClick={handleAddSubject}
                  className="mt-2 px-4 py-2 bg-green-600 text-white text-sm font-medium rounded shadow hover:bg-green-700"
                >
                  Add Subject
                </button>
              </div>

              <div>
                <label className="block font-medium text-gray-700">
                  Add Topics:
                </label>
                <input
                  type="text"
                  name="currentTopic"
                  value={formData.currentTopic}
                  onChange={(e) =>
                    setFormData({ ...formData, currentTopic: e.target.value })
                  }
                  placeholder="Topic name"
                  className="mt-1 w-full rounded-md border-gray-300 shadow-sm focus:border-green-500 focus:ring-green-500 sm:text-sm"
                />
                <button
                  type="button"
                  onClick={handleAddTopic}
                  className="mt-2 px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded shadow hover:bg-blue-700"
                >
                  Add Topic
                </button>
              </div>
            </div>
          </div>

          <div>
            <h2 className="text-lg font-bold text-gray-800">Timer Settings</h2>
            <div className="mt-3 space-y-2">
              {["noTimer", "perQuestion", "totalTime"].map((option) => (
                <label key={option} className="inline-flex items-center">
                  <input
                    type="radio"
                    name="timerOption"
                    value={option}
                    checked={timerOption === option}
                    onChange={handleTimerChange}
                    className="h-4 w-4 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="ml-2">
                    {option === "noTimer"
                      ? "No Timer"
                      : option === "perQuestion"
                      ? "Set Time Per Question"
                      : "Set Total Quiz Time"}
                  </span>
                </label>
              ))}
            </div>
          </div>

          <button
            type="submit"
            className="block w-full py-2 bg-blue-600 text-white font-medium text-lg rounded shadow hover:bg-blue-700"
          >
            Create Quiz
          </button>
        </form>
      </div>
    </div>
  );
};

export default QuizPage;
